// Filter to Steven's own self-chat, then append one JSON line to a local queue file.
// Requires NODE_FUNCTION_ALLOW_BUILTIN=fs,path,os on the n8n instance (see docker-compose.yml
// / install.sh) -- n8n's Code node blocks Node builtins by default; this is a deliberate,
// reviewed opt-in for exactly this file write, nothing else.
const OPENWA_SELF_CHAT_ID = 'REPLACE_WITH_REAL_SELF_CHAT_ID'; // set once C1 resolves it

const body = $json.body || {};
const data = body.data || {};
const result = { filtered: true, reason: null, chatId: data.chatId || null };

if (body.event !== 'message.received') {
  result.reason = 'not a message.received event';
  return { json: result };
}
if (OPENWA_SELF_CHAT_ID === 'REPLACE_WITH_REAL_SELF_CHAT_ID' || data.chatId !== OPENWA_SELF_CHAT_ID) {
  result.reason = 'chatId is not the configured self-chat (or self-chat id not yet set)';
  return { json: result };
}
if (data.fromMe !== true) {
  // Self-chat mode inverts the discriminator, same as mac-task-specs.md #5a: every real
  // message in a note-to-self thread carries fromMe true.
  result.reason = 'fromMe is not true';
  return { json: result };
}

const fs = require('fs');
const path = require('path');
const os = require('os');
const dir = path.join(os.homedir(), '.n8n-bridges');
fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
const record = {
  receivedAt: new Date().toISOString(),
  sessionId: body.sessionId || null,
  chatId: data.chatId || null,
  messageId: data.id || null,
  fromMe: data.fromMe === true,
  body: typeof data.body === 'string' ? data.body : null
};
const file = path.join(dir, 'openwa-selfchat-inbound.jsonl');
fs.appendFileSync(file, JSON.stringify(record) + '\n', { mode: 0o600 });

result.filtered = false;
result.queuedTo = file;
return { json: result };
